-- public.class_guard_take(p_world uuid, p_guard uuid, p_raw double precision, p_by text, p_for text)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.class_guard_take(p_world uuid, p_guard uuid, p_raw double precision, p_by text, p_for text)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare shield item;
begin
  shield := worn(p_world, p_guard, 'offhand');
  if shield.id is null then return; end if;
  update item set dmg = least(100, dmg + p_raw * 3 * pk(p_world, p_guard, 'worn:shield', 1)) where id = shield.id;
  perform skill_raise(p_world, p_guard, 'shields', 0.5);
  perform tell(p_world, p_guard, 'Guarded ' || p_for || ': ' || p_by || '’s blow taken on your '
    || lower((select name from item_def where id = shield.def)) || '.', 'fight');
end $function$
